qualified_questions.sparql_query:
PREFIX VideoGameOntology: <http://video-game-ontology.com/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT ?purpose 
WHERE {
    ?tutorial rdf:type VideoGameOntology:Tutorial .
    OPTIONAL { ?tutorial dc:description ?purpose . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>
PREFIX schema1: <http://schema1.example.com/>
PREFIX v1: <http://v1.example.com/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?player ?achievement ?gameEvent
WHERE {
    ?player rdf:type VideoGameOntology:Player .
    ?player VideoGameOntology:playsGame ?game .
    ?game rdf:type VideoGameOntology:Game .
    OPTIONAL { 
        ?player VideoGameOntology:achieves ?achievement .
    } .
    OPTIONAL { 
        ?player VideoGameOntology:participatesIn ?gameEvent .
    } .
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?game
WHERE {
    ?class rdfs:subClassOf VideoGameOntology:GameEvent .
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?event ?achievement ?behavior
WHERE {
    ?event rdf:type VideoGameOntology:InstantaneousEvent .
    ?achievement rdf:type VideoGameOntology:Achievement .
    OPTIONAL { 
        ?behavior rdf:type VideoGameOntology:PlayerBehavior .
    }
    ?event VideoGameOntology:eventTime ?time .
    FILTER NOT EXISTS { 
        ?achievement VideoGameOntology:eventTime ?time2 . 
        FILTER (?time2 != ?time)
    }
    OPTIONAL { 
        ?behavior VideoGameOntology:eventTime ?time3 .
        FILTER (?time3 = ?time)
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT DISTINCT ?property
WHERE {
    { ?property rdf:type owl:ObjectProperty ; rdfs:domain VideoGameOntology:Character ; rdfs:range VideoGameOntology:Item }
    UNION
    { ?property rdf:type owl:ObjectProperty ; rdfs:domain VideoGameOntology:Item ; rdfs:range VideoGameOntology:Character }
    UNION
    { ?property rdf:type owl:ObjectProperty ; rdfs:domain VideoGameOntology:Character ; rdfs:range ?o . 
      FILTER (?o != VideoGameOntology:Character && ?o = VideoGameOntology:Item) 
    }
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
SELECT ?player ?character
WHERE {
    ?player a VideoGameOntology:Player .
    ?player VideoGameOntology:ownsCharacter ?character .
    FILTER EXISTS { ?character a VideoGameOntology:Character }
}

PREFIX VideoGameOntology: <http://example.com/VideoGameOntology#>
SELECT ?character
WHERE {
    ?character VideoGameOntology:isCharacterInSession ?session .
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
SELECT ?character
WHERE {
    ?game a VideoGameOntology:Game .
    ?character VideoGameOntology:isCharacterInGame ?game .
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?game
WHERE {
    ?game a VideoGameOntology:Game .
    FILTER NOT EXISTS { 
        ?achievement VideoGameOntology:isAchievementInGame ?game . 
    }
    FILTER NOT EXISTS { 
        ?leaderboard VideoGameOntology:isLeaderboardInGame ?game . 
    }
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?restriction
WHERE {
    ?inAppPurchaseEvent rdf:type VideoGameOntology:InAppPurchaseEvent .
    ?inAppPurchaseEvent VideoGameOntology:purchasesGameOffering ?gameProduct .
    OPTIONAL { 
        ?gameProduct rdfs:comment ?restriction .
    }
    FILTER(EXISTS { ?gameProduct rdfs:comment ?restriction })
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology/>

SELECT ?objectProperty ?datatypeProperty
WHERE {
    ?objectProperty rdf:type owl:ObjectProperty .
    ?datatypeProperty rdf:type owl:DatatypeProperty .
    {
        { ?objectProperty rdfs:domain ?class . }
        UNION
        { ?objectProperty rdfs:range ?class . }
    }
}
